const request = $('Receive student question').first().json;
const body = request.body ?? request;
const question = String(body.question ?? '').trim();
if (!question) return [{ json: { error: 'Send a non-empty question in the question field.' } }];
const programs = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]).filter(p => p && (p.id || p.program));
return [{ json: { question, programs } }];

const raw = ($json.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('').trim();
try {
  const answer = JSON.parse(raw);
  return { json: { reply: String(answer.reply || 'I could not find that in the current program list.'), needs_staff: Boolean(answer.needs_staff) } };
} catch {
  return { json: { reply: 'I could not safely verify an answer from the current program list. Please contact the office for help.', needs_staff: true } };
}
